    grep -q '# book   :' "$helper_src" \
        && ok "a build says which book the script came from" \
        || bad "the book behind a script is not shown"
fi

# ---- accounts you can log in with, as a built-in step ----------------------- #
# This was last_build_step.sh: a script created once on the HOST and then owned
# by the person, running last in the chroot.  Wrong home twice over -- a fix to
# it reached nobody who already had a copy (that is how
# `chown: invalid user: 'wget:wget'` survived three releases), and setting the
# root password is not a matter of taste: book 8.5 says to do it.
#
# wget and the Python modules moved to `packagemanager setup`, which is where
# bootstrapping the tooling belongs.  The root password could NOT move there:
# setup runs on the booted system, and you need to log in to run it.
python3 - "$LFS_TOOL" <<'PY27'
import sys, importlib.machinery as m
lfs = m.SourceFileLoader('lfs', sys.argv[1]).load_module()
src = open(sys.argv[1]).read()
problems = []
# the old machinery must be gone, not merely unused
for gone in ("last_step_path", "ensure_last_step_script", "last_step_sources",
             "LAST_STEP_DEFAULT", "_write_last_step_copy"):
    if gone in src:
        problems.append("%s is still here" % gone)
# and the built-in step takes its place, last in the order
if 'order.append("init-accounts")' not in src:
    problems.append("init-accounts is not appended to the step order")
if problems:
    for p in problems:
        print("  FAIL  %s" % p)
    sys.exit(1)
print("  PASS  the final step is built in, not a script that can go stale")
PY27
_count_rc $?

# lfs-helper must actually perform it, and it must own no files
helper_src="$(dirname "$LFS_TOOL")/lfs-helper"
if [ -f "$helper_src" ]; then
  _p=""
  _slice_fn "$helper_src" cmd_init_accounts | grep -q 'passwd root' \
      || _p="$_p;init-accounts does not set the root password"
  # a non-interactive run must SAY what is missing, never block
  _slice_fn "$helper_src" cmd_init_accounts | grep -q '\[ ! -t 0 \]' \
      || _p="$_p;init-accounts would hang on a scripted run"
  case "$(_slice_fn "$helper_src" cmd_build)" in
      *'"$name" = "init-accounts"'*) ;;
      *) _p="$_p;lfs-helper would look for a book script for init-accounts" ;;
  esac
  case "$(_slice_fn "$helper_src" _is_not_a_package)" in
      *init-accounts*) ;;
      *) _p="$_p;init-accounts would be given a package user" ;;
  esac
  grep -q 'init-accounts)' "$helper_src" \
      || _p="$_p;init-accounts cannot be run by hand"
  if [ -n "$_p" ]; then
      printf '%s\n' "${_p#;}" | tr ';' '\n' | while IFS= read -r m; do
          [ -n "$m" ] && bad "$m"
      done
  else
      ok "the root password is set inside the chroot, before you can reboot"
  fi
fi

# ---- what the built system needs before it can fetch anything --------------- #
# LFS ships no download tool, so a freshly booted system cannot get the sources
# for its own next package.  The tarballs have to be on disk before the chroot
# is sealed, and get-sources is the last moment there is still a network.
#
# The LIST belongs to `packagemanager setup`, which is what installs them.  A
# copy in lfs would be a second thing to go stale -- the first version of this
# did exactly that, with a `bootstrap_packages` config key in lfs resolving wget
# separately from the tool that installs it.
python3 - "$LFS_TOOL" <<'PYBOOT'
import re, sys
src = open(sys.argv[1]).read()
problems = []
if not re.search(r"^def bootstrap_sources\(", src, re.M):
    problems.append("there is no bootstrap_sources")
m = re.search(r"^def bootstrap_sources\(.*?(?=\n\ndef )", src, re.S | re.M)
if m:
    body = m.group(0)
    if "packagemanager" not in body or "--sources" not in body:
        problems.append("lfs does not ask packagemanager what it needs")
    # lfs must not keep its own copy of the list.  CODE only -- the docstring
    # explains why the list lives elsewhere, and naming it there is the point.
    code = "\n".join("" if l.lstrip().startswith("#") else l
                     for l in body.splitlines())
    code = "".join(code.split('"""')[::2])
    if "wget" in code:
        problems.append("lfs still names the packages itself")
if "bootstrap_packages" in src.replace("`bootstrap_packages`", ""):
    problems.append("the old bootstrap_packages config key is still here")
if problems:
    for p in problems:
        print("  FAIL  %s" % p)
    sys.exit(1)
print("  PASS  lfs asks packagemanager what the new system needs downloaded")
PYBOOT
_count_rc $?

# and packagemanager must answer, without needing a booted system
pm_src="$(dirname "$LFS_TOOL")/packagemanager"
if [ -f "$pm_src" ]; then
  _p=""
  _out="$(python3 "$pm_src" setup --sources 2>/dev/null)"
  _n="$(printf '%s\n' "$_out" | grep -c '^https\?://')"
  [ "${_n:-0}" -ge 7 ] \
      || _p="$_p;setup --sources listed only $_n urls (expected the wheels at least)"
  # WHEELS, not sdists: a modern sdist needs its build backend and pip cannot
  # fetch one with no index -- BackendUnavailable: Cannot import hatchling.build
  printf '%s\n' "$_out" | grep -q 'requests-.*\.whl' \
      || _p="$_p;requests is not taken as a wheel"
  printf '%s\n' "$_out" | grep -q 'beautifulsoup4-.*\.whl' \
      || _p="$_p;beautifulsoup4 is not taken as a wheel"
  # and its dependencies, because it installs with --no-deps
  for _d in urllib3 charset_normalizer idna certifi soupsieve; do
      printf '%s\n' "$_out" | grep -q "$_d" \
          || _p="$_p;$_d is missing, and --no-deps will not pull it in"
  done
  # wget comes from the BOOK, not a hardcoded URL
  grep -q '_SETUP_BLFS_PACKAGES' "$pm_src" \
      || _p="$_p;wget is not resolved from the BLFS book"
  if [ -n "$_p" ]; then
      printf '%s\n' "${_p#;}" | tr ';' '\n' | while IFS= read -r m; do
          [ -n "$m" ] && bad "$m"
      done
  else
      ok "packagemanager setup declares what it needs, wheels and all"
  fi
fi

# ---- setup INSTALLS what it declares  (1.11.2) ------------------------------ #
# `--sources` worked and `--run` said "not implemented".  Everything below is a
# guarantee the old last_build_step.sh held and dropped when it was removed.
if [ -f "$pm_src" ]; then
python3 - "$pm_src" <<'PYSETUP'
import sys, re, importlib.machinery as m
src = open(sys.argv[1]).read()
pm = m.SourceFileLoader('pm', sys.argv[1]).load_module()
problems = []

def body(fn):
    mm = re.search(r"^def %s\(.*?(?=\n\ndef |\n\n# )" % fn, src, re.S | re.M)
    return mm.group(0) if mm else ""

# ONE implementation.  `pip` and `setup` want the same thing -- a module
# installed as its own package user -- and a second copy of it is how the two
# would drift apart, which is the species of bug this project keeps having.
if not re.search(r"^def pip_install_module\(", src, re.M):
    problems.append("there is no shared pip_install_module")
if "pip_install_module" not in body("cmd_pip"):
    problems.append("cmd_pip does not use the shared implementation")
if "pip_install_module" not in body("cmd_setup"):
    problems.append("setup does not use the shared implementation")

# THE ACCOUNT NAME IS ASKED FOR, NEVER ASSEMBLED.
# create_package_user normalises internally, so an unprefixed name creates
# `p_requests` and then hands `requests` to usermod and su:
#     usermod: user 'requests' does not exist
# Same species as `chown: invalid user: 'wget:wget'` at step 104 of 105.
b = body("pip_install_module")
if not re.search(r"pkgusr_name\(\s*_sanitise_user_name", b):
    problems.append("the pip account name skips the naming chokepoint")

# offline, and in order.  pip cannot reach an index on a fresh system: no CA
# certificates, so a lookup is a hang rather than an error.
sb = body("cmd_setup")
if "no_deps=True" not in sb:
    problems.append("setup lets pip resolve dependencies it cannot fetch")
if "find_links" not in sb:
    problems.append("setup does not install from the local wheels")
if "--no-index" not in b:
    problems.append("pip is still allowed to reach for an index")

# wget comes from the ordinary install path, not a private copy of it
if "wget" not in sb:
    problems.append("bootstrap no longer installs wget")
# it may delegate -- follow one hop rather than demanding the literal here
_wb = body("_setup_install_wget") + body("_install_via_self")
if '"install"' not in _wb:
    problems.append("wget is installed by some path other than `install`")

# THE FIVE STAGES.  What was missing was never the individual checks -- the
# tool could already tell you about wget, the book, make-ca and the bundle
# separately.  It was the ORDER, on a system where every one of them is
# unsatisfied at once and nothing says which to do first.
if not re.search(r"^_BOOTSTRAP_STAGES = \[", src, re.M):
    problems.append("the bootstrap stages are not a list anything can read")
for key in ("wget", "wheels", "book", "make_ca", "ca"):
    if '"%s"' % key not in body("_bootstrap_state"):
        problems.append("bootstrap does not check for %s" % key)
# stages 3-5 need a working download, so they are printed, never run
nb = body("_bootstrap_next_steps")
for cmd in ("blfs fetch", "make-ca", "make-ca -g --force"):
    if cmd not in nb:
        problems.append("the remaining steps do not mention %s" % cmd)
if "subprocess" in nb or "_run(" in nb:
    problems.append("the remaining steps are executed instead of printed")

# IDEMPOTENT.  The old final step ran exactly once, at the end of a six-hour
# build; this one has to be safe to run again after fixing whatever failed.
if "dist-info" not in src:
    problems.append("setup cannot tell what is already installed")
d, v, fn = pm._wheel_dist(
    "https://x/packages/py3/c/charset_normalizer/charset_normalizer-3.4.0-py3-none-any.whl")
if (d, v) != ("charset_normalizer", "3.4.0"):
    problems.append("the wheel filename is parsed as %r %r" % (d, v))
if fn != "charset_normalizer-3.4.0-py3-none-any.whl":
    problems.append("the wheel filename is not recovered from the url")

if problems:
    for x in problems:
        print("  FAIL  %s" % x)
    sys.exit(1)
print("  PASS  setup installs wget and the wheels, offline, as package users")
PYSETUP
_count_rc $?

# The old name must keep working.  `lfs build-system get-sources` on an
# already-installed system calls `packagemanager setup --sources`, and a rename
# that breaks the tool which downloads the sources costs a reboot to find out.
_o="$(python3 "$pm_src" setup --sources 2>/dev/null | grep -c '^https\?://')"
[ "${_o:-0}" -ge 7 ] \
    && ok "the old 'setup' name still answers --sources" \
    || bad "renaming setup broke the call get-sources makes"
_o="$(python3 "$pm_src" bootstrap --sources 2>/dev/null | grep -c '^https\?://')"
[ "${_o:-0}" -ge 7 ] \
    && ok "bootstrap --sources lists the wheels" \
    || bad "bootstrap --sources lists nothing"
# and lfs must ask for the new name, with the old one as the fallback
if grep -q '"packagemanager", "bootstrap", "--sources"' "$LFS_TOOL"; then
    grep -q '"packagemanager", "setup", "--sources"' "$LFS_TOOL" \
        && ok "get-sources asks for bootstrap, and falls back to setup" \
        || bad "get-sources cannot talk to an older packagemanager"
else
    bad "get-sources still asks for the old name only"
fi

# It must REFUSE rather than half-run when the wheels were never downloaded.
# There is no network on a fresh system, so "try it and see" is a hang.
#
# On a system that is ALREADY bootstrapped there is nothing left for setup to
# install, so exit 0 with an empty sources dir is the truth, not the bug this
# guards against.  That state is skipped, not failed -- the refusal path can
# only be exercised where something is still missing.
_sbx="$T/setup-empty"; mkdir -p "$_sbx"
_o="$(LFS_SOURCES_DIR="$_sbx" python3 "$pm_src" setup --run --yes 2>&1)"; _rc=$?
if [ "$_rc" -eq 0 ] && ! printf '%s\n' "$_o" | grep -q '^  --  '; then
    echo "  SKIP  setup has nothing left to install on this system"
else
_p=""
[ "$_rc" -ne 0 ] || _p="$_p;setup --run succeeded with no wheels on disk"
printf '%s\n' "$_o" | grep -q 'get-sources' \
    || _p="$_p;it does not say where the wheels were supposed to come from"
printf '%s\n' "$_o" | grep -q 'requests-.*\.whl' \
    || _p="$_p;it does not name the files it could not find"
if [ -n "$_p" ]; then
    printf '%s\n' "${_p#;}" | tr ';' '\n' | while IFS= read -r m; do
        [ -n "$m" ] && bad "$m"
    done
else
    ok "setup stops when the wheels are missing, and says which"
fi
fi
fi



# the dry run must print EVERY url, not a sample
grep -q "print the WHOLE list" "$LFS_TOOL" \
    && ok "get-sources lists every URL in a dry run" \
    || bad "the dry run truncates the list"

# ---- `lfs` must know when it is inside the chroot ---------------------------- #
# The build is driven from OUTSIDE.  Inside, $LFS does not exist as a path, so
# `lfs build-system next` read empty state and reported "2 of 12 done" for a
# FINISHED build -- sending you back to the beginning.
python3 - "$LFS_TOOL" <<'PY28'
import sys, importlib.machinery as m
lfs = m.SourceFileLoader('lfs', sys.argv[1]).load_module()
problems = []
if not hasattr(lfs, "inside_chroot"):
    problems.append("nothing detects the chroot")
for c in ("next", "session", "layout", "crosschain", "chroot"):
    if c not in lfs._INSIDE_ONLY_ELSEWHERE:
        problems.append("'%s' would still run inside the chroot" % c)
# ...but reading the book and managing packages must still work in there
for c in ("books", "config", "packages", "install", "update"):
    if c in lfs._INSIDE_ONLY_ELSEWHERE:
        problems.append("'%s' should still work inside the chroot" % c)
if lfs._INSIDE_EQUIVALENT.get("next") != "lfs-helper next":
    problems.append("the redirect does not name lfs-helper")
if problems:
    for p in problems: print("  FAIL  %s" % p)
    sys.exit(1)
print("  PASS  build commands redirect to lfs-helper inside the chroot")
