import sys, importlib.machinery as m
lfs = m.SourceFileLoader('lfs', sys.argv[1]).load_module()
src = open(sys.argv[1]).read()
problems = []
for c in ('"run"', '"next"', '"list"', '"snapshot"', '"set-book"'):
