    grep -qw 'systemctl' "$PHASES_LIB" \
        || _p="$_p;a missing systemctl still aborts generated scripts"
    grep -q 'command -v "\$c" >/dev/null 2>&1 && continue' "$PHASES_LIB" \
        || _p="$_p;the systemd shims would shadow the real commands"
