: > "$_lkd/usr/lib/libowned.so.1.13.0"
ln -s libowned.so.1.13.0 "$_lkd/usr/lib/libowned.so.1"
printf '%s/usr/lib/libowned.so.1.13.0\n' "$_lkd" > "$_lkd/man/theowner.files"
